    private static func samplesAnnouncements() -> [L10nCatalogSample] {
        var s: [L10nCatalogSample] = []
        s.append(L10nCatalogSample(key: "announcements.call_guide_dashboard.body.p1", table: "Announcements", bundles: ["app"], languagesWithValue: ["ja", "ko"], args: "", make: { L10n.Announcements.callGuideDashboardBodyP1 }, expected: ["ja": "プロデュースに「コールガイド」を追加しました。コールが入っている曲、最近誰がどの曲を書いたか、「コール曲」タグが付いているのにまだ書かれていない曲が、1 つの画面で見られます。", "ko": "프로듀스에 “콜 가이드”를 추가했어요. 콜이 들어간 곡, 최근 누가 어떤 곡을 썼는지, “콜 곡” 태그가 붙어 있는데 아직 작성되지 않은 곡을 한 화면에서 볼 수 있어요."]))
        s.append(L10nCatalogSample(key: "announcements.call_guide_dashboard.body.p2", table: "Announcements", bundles: ["app"], languagesWithValue: ["ja", "ko"], args: "", make: { L10n.Announcements.callGuideDashboardBodyP2 }, expected: ["ja": "書かれていない曲の行から「書く」を押すと、その曲の歌詞タブがそのまま開きます。歌詞の語をタップしてコールを付けて保存するだけです。ログインしていれば誰でも書けます。", "ko": "작성되지 않은 곡의 줄에서 “쓰기”를 누르면 그 곡의 가사 탭이 바로 열려요. 가사의 단어를 탭해서 콜을 달고 저장하기만 하면 돼요. 로그인했다면 누구나 쓸 수 있어요."]))
        s.append(L10nCatalogSample(key: "announcements.call_guide_dashboard.body.p3", table: "Announcements", bundles: ["app"], languagesWithValue: ["ja", "ko"], args: "", make: { L10n.Announcements.callGuideDashboardBodyP3 }, expected: ["ja": "曲一覧の絞り込みに「コールガイドがある曲のみ」を追加しました。ライブ前に、コールのある曲だけを並べて予習できます。", "ko": "곡 목록의 필터에 “콜 가이드가 있는 곡만”을 추가했어요. 라이브 전에 콜이 있는 곡만 늘어놓고 예습할 수 있어요."]))
        s.append(L10nCatalogSample(key: "announcements.call_guide_dashboard.body.p4", table: "Announcements", bundles: ["app"], languagesWithValue: ["ja", "ko"], args: "", make: { L10n.Announcements.callGuideDashboardBodyP4 }, expected: ["ja": "コールの編集には履歴が残るようになりました。誰がいつどの曲を書いたかが「最近の編集」に出ます (歌詞やコールの中身は履歴に残しません)。", "ko": "콜을 편집하면 기록이 남게 됐어요. 누가 언제 어떤 곡을 썼는지가 “최근 편집”에 나와요 (가사나 콜의 내용은 기록에 남기지 않아요)."]))
        s.append(L10nCatalogSample(key: "announcements.call_guide_dashboard.summary", table: "Announcements", bundles: ["app"], languagesWithValue: ["ja", "ko"], args: "", make: { L10n.Announcements.callGuideDashboardSummary }, expected: ["ja": "コールが入っている曲・最近の編集・まだ書かれていない曲を 1 枚にまとめました。", "ko": "콜이 들어간 곡·최근 편집·아직 작성되지 않은 곡을 한 화면에 모았어요."]))
        s.append(L10nCatalogSample(key: "announcements.call_guide_dashboard.title", table: "Announcements", bundles: ["app"], languagesWithValue: ["ja", "ko"], args: "", make: { L10n.Announcements.callGuideDashboardTitle }, expected: ["ja": "コールガイドを、みんなで書けるように", "ko": "콜 가이드를 모두 함께 쓸 수 있게"]))
        s.append(L10nCatalogSample(key: "announcements.call_response_retired.body.p1", table: "Announcements", bundles: ["app"], languagesWithValue: ["ja", "ko"], args: "", make: { L10n.Announcements.callResponseRetiredBodyP1 }, expected: ["ja": "曲の「コミュニティ」にあった「コーレス」(曲ごとにコールを文章で書く欄) をなくしました。歌詞の行ごとに「ここでこう叫ぶ」を付けられるコールガイドができて、役目が重なっていたためです。", "ko": "곡의 “커뮤니티”에 있던 “콜 앤 리스폰스” (곡마다 콜을 문장으로 쓰는 란)를 없앴어요. 가사의 줄마다 “여기서 이렇게 외친다”를 달 수 있는 콜 가이드가 생겨서 역할이 겹쳤기 때문이에요."]))
